"""Cases: board, overview map, page, lifecycle, ranking, tags, merge / split.

Confirming a case for a line generates its requirement(s) in the same request.
"""

from __future__ import annotations

from typing import Literal

from fastapi import APIRouter, Depends, HTTPException, Query
from pydantic import BaseModel

from app import audit
from app.api.auth import User, current_user, require_pm
from app.api.deps import conn, request_id
from app.cases import cluster, lifecycle, pages, queries
from app.requirements import generator
from app.scoring import rank

router = APIRouter(prefix="/cases", tags=["cases"])


def _vehicles(c, case_id: str) -> list[str]:
    rows = c.execute("select vehicle from case_vehicle where case_id = %s", (case_id,)).fetchall()
    if not rows and not c.execute("select 1 from case_item where id = %s", (case_id,)).fetchone():
        raise HTTPException(404, f"{case_id} not found")
    return [r["vehicle"] for r in rows]


def _require_pm_of_case(c, user: User, case_id: str) -> None:
    vehicles = _vehicles(c, case_id)
    if user.role not in ("pm", "admin"):
        raise HTTPException(403, "only a PM can do this")
    if vehicles and not any(user.owns(v) for v in vehicles):
        raise HTTPException(403, f"{case_id} applies to none of your lines")


@router.get("")
def board(profile_id: str, state: list[str] = Query(default=["open", "confirmed"]), car_area: str | None = None,
          release_fit: str | None = None, market: str | None = None, source_type: str | None = None,
          source_id: str | None = None, aspect_group: str | None = None, conflict_only: bool = False,
          q: str | None = None, c=Depends(conn), user: User = Depends(current_user)) -> list[dict]:
    """Ranked case board of one weight profile (= one vehicle + market). Filters: state,
    car area, release fit, market (customers there), source type (content type), source."""
    bad = set(state) - set(queries.STATES)
    if bad:
        raise HTTPException(422, f"unknown states {sorted(bad)}")
    if not c.execute("select 1 from weight_profile where id = %s", (profile_id,)).fetchone():
        raise HTTPException(404, "weight profile not found")
    return queries.board(c, profile_id, states=tuple(state), car_area=car_area, release_fit=release_fit,
                         market=market, source_type=source_type, source_id=source_id, aspect_group=aspect_group,
                         conflict_only=conflict_only, q=q)


@router.get("/overview")
def overview(vehicle: str, c=Depends(conn), user: User = Depends(current_user)) -> list[dict]:
    """Overview map of a line: cases (observed included) per car area and state."""
    return queries.overview(c, vehicle)


@router.get("/{case_id}")
def get_case(case_id: str, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    page = queries.page(c, case_id)
    if page is None:
        raise HTTPException(404, f"{case_id} not found")
    audit.log_access(c, action="view", object_type="case", object_id=case_id, actor=user.actor,
                     request_id=request_id())
    return page


@router.get("/{case_id}/versions")
def versions(case_id: str, c=Depends(conn), user: User = Depends(current_user)) -> list[dict]:
    return c.execute("select version, body_md, author, created_at from page_version where object_type = 'case'"
                     " and object_id = %s order by version desc", (case_id,)).fetchall()


class PageSave(BaseModel):
    body_md: str
    expected_version: int
    title: str | None = None


@router.put("/{case_id}/page")
def save_page(case_id: str, body: PageSave, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """Save the page; 409 when someone saved first (stale version)."""
    _require_pm_of_case(c, user, case_id)
    row = pages.save_case_page(c, case_id, body.body_md, body.expected_version, actor=user.actor, title=body.title,
                               request_id=request_id())
    return {"id": row["id"], "title": row["title"], "body_version": row["body_version"]}


class Transition(BaseModel):
    action: Literal["open", "confirm", "reject", "reopen"]
    rationale: str | None = None


@router.post("/{case_id}/vehicles/{vehicle}/transition")
def transition(case_id: str, vehicle: str, body: Transition, c=Depends(conn),
               user: User = Depends(current_user)) -> dict:
    """PM lifecycle action for one line. Confirm generates the requirement(s)."""
    require_pm(user, vehicle)
    row = lifecycle.transition(c, case_id, vehicle, body.action, actor=user.actor, rationale=body.rationale,
                               request_id=request_id())
    out = {"case_id": case_id, "vehicle": vehicle, "state": row["state"], "requirements": []}
    if body.action == "confirm":
        created = generator.generate(c, case_id, vehicle, request_id=request_id())
        out["requirements"] = [r["id"] for r in created]
    return out


class Rank(BaseModel):
    rank: int | None
    reason: str | None = None


@router.post("/{case_id}/vehicles/{vehicle}/rank")
def set_rank(case_id: str, vehicle: str, body: Rank, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """Drag on the board: a manual rank with a reason (null clears it)."""
    require_pm(user, vehicle)
    row = rank.set_manual_rank(c, case_id, vehicle, body.rank, actor=user.actor, reason=body.reason,
                               request_id=request_id())
    return {k: row[k] for k in ("case_id", "vehicle", "manual_rank", "manual_rank_reason")}


class Tag(BaseModel):
    field: Literal["brand_fit", "segment", "release_fit"]
    value: str
    rationale: str
    vehicle: str | None = None


TAG_VALUES = {"brand_fit": {"fits", "neutral", "off_brand"}, "segment": {"base", "premium", "luxury"},
              "release_fit": {"current_car", "next_gen", "ota"}}


@router.post("/{case_id}/tags")
def set_tag(case_id: str, body: Tag, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """PM override of an AI tag (brand fit, segment, or release fit per line)."""
    if body.value not in TAG_VALUES[body.field]:
        raise HTTPException(422, f"{body.field} is one of {sorted(TAG_VALUES[body.field])}")
    if body.vehicle:
        require_pm(user, body.vehicle)
    else:
        _require_pm_of_case(c, user, case_id)
    row = pages.set_tag(c, case_id, body.field, body.value, actor=user.actor, rationale=body.rationale,
                        vehicle=body.vehicle, request_id=request_id())
    row.pop("embedding", None)
    return row


class Merge(BaseModel):
    target_id: str
    rationale: str


@router.post("/{case_id}/merge")
def merge(case_id: str, body: Merge, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """Move every signal of this case into the target; this case stays as rejected, pointing to it."""
    _require_pm_of_case(c, user, case_id)
    _vehicles(c, body.target_id)
    a = c.execute("select feature_id from case_item where id = %s", (case_id,)).fetchone()
    b = c.execute("select feature_id from case_item where id = %s", (body.target_id,)).fetchone()
    if a["feature_id"] != b["feature_id"]:
        raise HTTPException(422, "cases of different topics cannot be merged (grouping never crosses a topic)")
    cluster.merge(c, case_id, body.target_id, actor=user.actor, rationale=body.rationale)
    audit.insert(c, "decision", {"object_type": "case", "object_id": case_id, "actor": user.actor,
                                 "action": "merge", "rationale": f"into {body.target_id}: {body.rationale}"},
                 actor=user.actor, request_id=request_id())
    _refresh(c, body.target_id)
    return {"merged": case_id, "into": body.target_id}


class Split(BaseModel):
    signal_ids: list[str]
    rationale: str


@router.post("/{case_id}/split", status_code=201)
def split(case_id: str, body: Split, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """Move the selected signals into a new case of the same topic and aspect group."""
    _require_pm_of_case(c, user, case_id)
    new = cluster.split(c, case_id, body.signal_ids, actor=user.actor, rationale=body.rationale)
    audit.insert(c, "decision", {"object_type": "case", "object_id": case_id, "actor": user.actor,
                                 "action": "split", "rationale": f"{new['id']}: {body.rationale}"},
                 actor=user.actor, request_id=request_id())
    _refresh(c, case_id)
    _refresh(c, new["id"])
    return {"from": case_id, "new_case": new["id"], "title": new["title"]}


def _refresh(c, case_id: str) -> None:
    """Figures, tags and open rules after a membership change; then rescore the lines' configs."""
    from app.cases import pipeline
    from app.scoring import score

    pipeline.update_case(c, case_id)
    for cfg in c.execute("select distinct cfg.id from config cfg join case_vehicle cv on cv.vehicle = cfg.vehicle"
                         " where cv.case_id = %s and cfg.active", (case_id,)).fetchall():
        score.score_config(c, cfg["id"], case_ids=[case_id])


@router.post("/{case_id}/vehicles/{vehicle}/requirements", status_code=201)
def generate_requirements(case_id: str, vehicle: str, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """(Re)generate missing requirements of a confirmed case, e.g. after one was deleted."""
    require_pm(user, vehicle)
    created = generator.generate(c, case_id, vehicle, request_id=request_id())
    return {"requirements": [r["id"] for r in created]}

"""Requirements: board, page, status flow, re-target, cost, rank, tombstone delete,
handover export of the approved top 10 (logged)."""

from __future__ import annotations

import csv
import io
from typing import Literal

from fastapi import APIRouter, Depends, HTTPException, Query
from fastapi.responses import PlainTextResponse
from pydantic import BaseModel

from app import audit
from app.api.auth import User, current_user, require_editor, require_pm
from app.api.deps import conn, request_id
from app.requirements import service

router = APIRouter(prefix="/requirements", tags=["requirements"])
STATUSES = ("draft", "in_discussion", "approved", "rejected", "deleted")


def _vehicle(c, rid: str) -> str:
    row = c.execute("select vehicle from requirement where id = %s", (rid,)).fetchone()
    if row is None:
        raise HTTPException(404, f"{rid} not found")
    return row["vehicle"]


@router.get("")
def board(profile_id: str, status: list[str] = Query(default=["draft", "in_discussion", "approved"]),
          release_target: str | None = None, car_area: str | None = None, market: str | None = None,
          c=Depends(conn), user: User = Depends(current_user)) -> list[dict]:
    """Requirements of the profile's line ranked for this profile (case score x cost multiplier)."""
    bad = set(status) - set(STATUSES)
    if bad:
        raise HTTPException(422, f"unknown statuses {sorted(bad)}")
    if not c.execute("select 1 from weight_profile where id = %s", (profile_id,)).fetchone():
        raise HTTPException(404, "weight profile not found")
    rows = service.board(c, profile_id, statuses=tuple(status))
    areas = {r["id"]: r for r in c.execute(
        "select r.id, f.car_area, f.name as topic from requirement r join case_item ci on ci.id = r.case_id"
        " join feature f on f.id = ci.feature_id where r.id = any(%s)", ([r["id"] for r in rows],)).fetchall()}
    out = []
    for r in rows:
        r.update(car_area=areas[r["id"]]["car_area"], topic=areas[r["id"]]["topic"])
        if release_target and r["release_target"] != release_target:
            continue
        if car_area and r["car_area"] != car_area:
            continue
        if market and r["market"] not in (None, market):
            continue
        out.append(r)
    return out


@router.get("/export")
def export(profile_id: str, format: Literal["json", "csv"] = "json", top_n: int = 10, c=Depends(conn),
           user: User = Depends(current_user)):
    """Handover to engineering: the approved top N with their arguments (customer
    complaints, wishes, competition, cost). The codebeamer / Jira format is a later
    feature; the export is logged as a decision and an audit event."""
    profile = c.execute("select p.id, c.vehicle, c.market, p.name from weight_profile p join config c"
                        " on c.id = p.config_id where p.id = %s", (profile_id,)).fetchone()
    if profile is None:
        raise HTTPException(404, "weight profile not found")
    rows = service.board(c, profile_id, statuses=("approved",))[:top_n]
    items = []
    for r in rows:
        req = c.execute("select * from requirement where id = %s", (r["id"],)).fetchone()
        fig = c.execute("select figures from case_item where id = %s", (r["case_id"],)).fetchone()["figures"] or {}
        vf = fig.get("by_vehicle", {}).get(profile["vehicle"], {})
        m = vf.get("markets", {}).get(profile["market"], {})
        items.append({
            "rank": r["rank"], "id": r["id"], "title": req["title"], "case_id": r["case_id"],
            "release_target": req["release_target"], "evidence_level": req["evidence_level"],
            "complaints": m.get("complaints", 0), "wishes": m.get("wishes", 0), "customers": m.get("customers", 0),
            "defects": m.get("defects", 0),
            "competition": f"{vf.get('competitor_evidence', {}).get('signals', 0)} competitor signals, "
                           f"{len(vf.get('competitor_offers', []))} competitor facts",
            "cost_size": req["cost_size"], "cost_source": req["cost_source"],
            "metric_target": req["metric_target"], "acceptance_criteria": req["acceptance_criteria"],
            "rank_score": r["rank_score"],
        })
        audit.insert(c, "decision", {"object_type": "requirement", "object_id": r["id"], "vehicle": req["vehicle"],
                                     "actor": user.actor, "action": "export",
                                     "rationale": f"export {format}, profile {profile['name']}"},
                     actor=user.actor, request_id=request_id())
    audit.log_access(c, action="export", object_type="weight_profile", object_id=str(profile_id), actor=user.actor,
                     request_id=request_id())
    if format == "json":
        return {"vehicle": profile["vehicle"], "market": profile["market"], "profile": profile["name"],
                "items": items}
    buf = io.StringIO()
    fields = ["rank", "id", "title", "case_id", "release_target", "evidence_level", "customers", "complaints",
              "wishes", "defects", "competition", "cost_size", "cost_source", "rank_score"]
    writer = csv.DictWriter(buf, fieldnames=fields, extrasaction="ignore")
    writer.writeheader()
    writer.writerows(items)
    return PlainTextResponse(buf.getvalue(), media_type="text/csv")


@router.get("/{rid}")
def get_requirement(rid: str, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    row = c.execute("select * from requirement where id = %s", (rid,)).fetchone()
    if row is None:
        raise HTTPException(404, f"{rid} not found")
    row["case"] = c.execute("select c.id, c.title, c.aspect_group, f.topic_id, f.name as topic, f.car_area"
                            " from case_item c join feature f on f.id = c.feature_id where c.id = %s",
                            (row["case_id"],)).fetchone()
    row["decisions"] = c.execute("select actor, action, rationale, created_at from decision where"
                                 " object_type = 'requirement' and object_id = %s order by created_at desc",
                                 (rid,)).fetchall()
    row["ranks"] = c.execute("select weight_profile_id, rank_score, cost_missing from requirement_rank"
                             " where requirement_id = %s", (rid,)).fetchall()
    audit.log_access(c, action="view", object_type="requirement", object_id=rid, actor=user.actor,
                     request_id=request_id())
    return row


@router.get("/{rid}/versions")
def versions(rid: str, c=Depends(conn), user: User = Depends(current_user)) -> list[dict]:
    return c.execute("select version, body_md, author, created_at from page_version where"
                     " object_type = 'requirement' and object_id = %s order by version desc", (rid,)).fetchall()


class PageSave(BaseModel):
    body_md: str
    expected_version: int


@router.put("/{rid}/page")
def save_page(rid: str, body: PageSave, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    require_editor(user, _vehicle(c, rid))
    row = service.save_page(c, rid, body.body_md, body.expected_version, actor=user.actor, request_id=request_id())
    return {"id": row["id"], "body_version": row["body_version"]}


class Status(BaseModel):
    status: Literal["draft", "in_discussion", "approved", "rejected"]
    rationale: str | None = None


@router.post("/{rid}/status")
def set_status(rid: str, body: Status, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    vehicle = _vehicle(c, rid)
    if body.status == "approved":
        require_pm(user, vehicle)
    else:
        require_editor(user, vehicle)
    row = service.set_status(c, rid, body.status, actor=user.actor, rationale=body.rationale,
                             request_id=request_id())
    return {"id": row["id"], "status": row["status"]}


class Retarget(BaseModel):
    release_target: Literal["next_gen", "current_car", "ota"]
    rationale: str


@router.post("/{rid}/retarget")
def retarget(rid: str, body: Retarget, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    require_editor(user, _vehicle(c, rid))
    row = service.retarget(c, rid, body.release_target, actor=user.actor, rationale=body.rationale,
                           request_id=request_id())
    return {"id": row["id"], "release_target": row["release_target"]}


class Cost(BaseModel):
    cost_size: Literal["S", "M", "L"]
    rationale: str


@router.post("/{rid}/cost")
def set_cost(rid: str, body: Cost, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    require_editor(user, _vehicle(c, rid))
    row = service.set_cost(c, rid, body.cost_size, actor=user.actor, rationale=body.rationale,
                           request_id=request_id())
    return {"id": row["id"], "cost_size": row["cost_size"], "cost_source": row["cost_source"]}


class Rank(BaseModel):
    rank: int | None
    reason: str | None = None


@router.post("/{rid}/rank")
def set_rank(rid: str, body: Rank, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    require_pm(user, _vehicle(c, rid))
    row = service.set_manual_rank(c, rid, body.rank, actor=user.actor, reason=body.reason, request_id=request_id())
    return {"id": row["id"], "manual_rank": row["manual_rank"], "manual_rank_reason": row["manual_rank_reason"]}


class Delete(BaseModel):
    rationale: str


@router.post("/{rid}/delete")
def delete(rid: str, body: Delete, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """Tombstone: title and body purged, row and history kept."""
    require_editor(user, _vehicle(c, rid))
    row = service.delete(c, rid, actor=user.actor, rationale=body.rationale, request_id=request_id())
    return {"id": row["id"], "status": row["status"], "deleted_at": row["deleted_at"]}

"""RAG sidebar chat, audit trail, notifications, agent runs, RAG index rebuild."""

from __future__ import annotations

from typing import Literal

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

from app.api.auth import User, current_user, require_editor, require_pm
from app.api.deps import conn, request_id
from app.rag import agent, index

router = APIRouter(tags=["collaboration"])
ObjectType = Literal["case", "requirement"]


def _exists(c, object_type: str, object_id: str) -> str | None:
    """The object's vehicle (requirement) or None (case); 404 when it does not exist."""
    table = "case_item" if object_type == "case" else "requirement"
    row = c.execute(f"select {'null' if object_type == 'case' else 'vehicle'} as vehicle from {table}"
                    " where id = %s", (object_id,)).fetchone()
    if row is None:
        raise HTTPException(404, f"{object_id} not found")
    return row["vehicle"]


@router.get("/chat/{object_type}/{object_id}")
def history(object_type: ObjectType, object_id: str, c=Depends(conn), user: User = Depends(current_user)):
    _exists(c, object_type, object_id)
    return c.execute("select * from chat_message where object_type = %s and object_id = %s order by created_at",
                     (object_type, object_id)).fetchall()


class Question(BaseModel):
    question: str


@router.post("/chat/{object_type}/{object_id}")
def ask(object_type: ObjectType, object_id: str, body: Question, c=Depends(conn),
        user: User = Depends(current_user)) -> dict:
    """Ask the sidebar agent. Every claim cites a signal it retrieved; otherwise
    "No evidence found". Edits come back as a proposed diff the PM accepts or rejects."""
    _exists(c, object_type, object_id)
    return agent.ask(c, object_type, object_id, body.question, actor=user.actor, request_id=request_id())


class EditDecision(BaseModel):
    accept: bool


@router.post("/chat/messages/{message_id}/decision")
def decide(message_id: str, body: EditDecision, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    msg = c.execute("select object_type, object_id from chat_message where id = %s", (message_id,)).fetchone()
    if msg is None:
        raise HTTPException(404, "message not found")
    vehicle = _exists(c, msg["object_type"], msg["object_id"])
    if msg["object_type"] == "case":
        require_pm(user)
    else:
        require_editor(user, vehicle)
    row = agent.decide_edit(c, message_id, body.accept, actor=user.actor, request_id=request_id())
    if body.accept:
        index.refresh_page(c, msg["object_type"], msg["object_id"])
    return {"id": str(row["id"]), "diff_status": row["diff_status"]}


@router.get("/audit/{object_type}/{object_id}")
def audit_trail(object_type: str, object_id: str, limit: int = 200, c=Depends(conn),
                user: User = Depends(current_user)) -> list[dict]:
    """Audit events of one object (for a case also its per-line rows ``case_vehicle``)."""
    types = [object_type] + (["case_vehicle"] if object_type == "case" else [])
    return c.execute(
        "select seq, at, actor, actor_type, action, object_type, object_id, before, after, rationale, run_id,"
        " request_id from audit_event where object_type = any(%s) and (object_id = %s or object_id like %s)"
        " order by seq desc limit %s", (types, object_id, f"{object_id}/%", min(limit, 1000))).fetchall()


@router.get("/audit/chain/{requirement_id}")
def chain(requirement_id: str, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """Audit chain of one requirement: source records -> signals -> case -> scores ->
    PM decisions -> requirement -> approval."""
    from app.reports import audit_chain

    return audit_chain.collect(c, requirement_id)


@router.get("/notifications")
def notifications(vehicle: str | None = None, unread: bool = False, limit: int = 50, c=Depends(conn),
                  user: User = Depends(current_user)) -> list[dict]:
    vehicles = [vehicle] if vehicle else list(user.vehicles)
    return c.execute(
        "select id, type, object_type, object_id, vehicle, market, message, created_at,"
        " %s::uuid = any(read_by) as read from notification"
        " where (cardinality(%s::text[]) = 0 or vehicle is null or vehicle = any(%s::text[]))"
        " and (not %s or not (%s::uuid = any(read_by)))"
        " order by created_at desc limit %s",
        (user.id, vehicles, vehicles, unread, user.id, min(limit, 500))).fetchall()


@router.post("/notifications/{notification_id}/read")
def mark_read(notification_id: str, c=Depends(conn), user: User = Depends(current_user)) -> dict:
    """Read receipts are per-user UI state, not a decision: no audit event."""
    row = c.execute("update notification set read_by = array_append(read_by, %s::uuid) where id = %s"
                    " and not (%s::uuid = any(read_by)) returning id", (user.id, notification_id, user.id)).fetchone()
    return {"id": notification_id, "updated": row is not None}


@router.get("/runs")
def runs(limit: int = 50, c=Depends(conn), user: User = Depends(current_user)) -> list[dict]:
    return c.execute("select id, agent, mode, status, started_at, ended_at, records_fetched, signals_valid,"
                     " signals_quarantined, llm_tokens, llm_cost_usd, error, params from agent_run"
                     " order by started_at desc limit %s", (min(limit, 500),)).fetchall()


